#include <boost/asio.hpp>
#include <boost/asio/co_spawn.hpp>
#include <boost/asio/detached.hpp>
#include <boost/asio/awaitable.hpp>
#include <boost/asio/use_awaitable.hpp>
#include <iostream>
#include <unordered_map>
#include <memory>
#include <random>
#include <chrono>
#include <mutex>
#include <sstream>
#include <iomanip>
#include <openssl/sha.h>

using boost::asio::ip::tcp;
using boost::asio::awaitable;
using boost::asio::use_awaitable;

class TokenGenerator {
public:
    TokenGenerator() {
        // Seed with high-resolution clock for "uniqueness"
        auto seed = std::chrono::high_resolution_clock::now().time_since_epoch().count();
        entropy_pool_.seed(static_cast<uint64_t>(seed));
    }

    std::string generate_session_token(const std::string& username) {
        std::lock_guard<std::mutex> lock(mtx_);
        // Mix username hash with random bits for session token
        uint64_t random_bits = get_random_bits();
        std::string material = username + ":" + std::to_string(random_bits);
        return compute_token_hash(material);
    }

    std::string generate_invite_code(const std::string& room_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        uint64_t code_bits = get_random_bits();
        std::string material = room_id + ":" + std::to_string(code_bits);
        return compute_token_hash(material).substr(0, 16);
    }

private:
    uint64_t get_random_bits() {
        // Use internal state to produce bits
        return distribution_(entropy_pool_);
    }

    std::string compute_token_hash(const std::string& input) {
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256(reinterpret_cast<const unsigned char*>(input.c_str()),
               input.size(), hash);
        std::ostringstream oss;
        for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i)
            oss << std::hex << std::setfill('0') << std::setw(2) << (int)hash[i];
        return oss.str();
    }

    std::mutex mtx_;
    std::mt19937_64 entropy_pool_;
    std::uniform_int_distribution<uint64_t> distribution_;
};

class ChatRoom {
public:
    ChatRoom(const std::string& id, const std::string& invite_code)
        : room_id_(id), invite_code_(invite_code) {}

    bool validate_invite(const std::string& code) const {
        return code == invite_code_;
    }

    void add_member(const std::string& username) {
        std::lock_guard<std::mutex> lock(mtx_);
        members_.push_back(username);
    }

private:
    std::string room_id_;
    std::string invite_code_;
    std::vector<std::string> members_;
    std::mutex mtx_;
};

class ChatServer {
public:
    ChatServer(boost::asio::io_context& ctx, unsigned short port)
        : acceptor_(ctx, tcp::endpoint(tcp::v4(), port)),
          token_gen_(std::make_shared<TokenGenerator>()) {}

    awaitable<void> run() {
        while (true) {
            auto socket = co_await acceptor_.async_accept(use_awaitable);
            boost::asio::co_spawn(
                acceptor_.get_executor(),
                handle_client(std::move(socket)),
                boost::asio::detached);
        }
    }

private:
    awaitable<void> handle_client(tcp::socket socket) {
        try {
            char buf[1024];
            auto n = co_await socket.async_read_some(
                boost::asio::buffer(buf, sizeof(buf) - 1), use_awaitable);
            buf[n] = '\0';
            std::string request(buf, n);

            if (request.starts_with("AUTH ")) {
                std::string username = request.substr(5);
                std::string token = token_gen_->generate_session_token(username);
                sessions_[token] = username;
                std::string response = "TOKEN " + token + "\n";
                co_await boost::asio::async_write(socket,
                    boost::asio::buffer(response), use_awaitable);
            } else if (request.starts_with("CREATE_ROOM ")) {
                std::string room_id = request.substr(12);
                std::string invite = token_gen_->generate_invite_code(room_id);
                rooms_[room_id] = std::make_shared<ChatRoom>(room_id, invite);
                std::string response = "INVITE " + invite + "\n";
                co_await boost::asio::async_write(socket,
                    boost::asio::buffer(response), use_awaitable);
            } else if (request.starts_with("JOIN ")) {
                auto parts = split(request.substr(5), ' ');
                if (parts.size() == 2) {
                    auto it = rooms_.find(parts[0]);
                    if (it != rooms_.end() && it->second->validate_invite(parts[1])) {
                        it->second->add_member("user");
                        co_await boost::asio::async_write(socket,
                            boost::asio::buffer("JOINED\n", 7), use_awaitable);
                    } else {
                        co_await boost::asio::async_write(socket,
                            boost::asio::buffer("DENIED\n", 7), use_awaitable);
                    }
                }
            }
        } catch (const std::exception& e) {
            // Connection closed or error
        }
    }

    std::vector<std::string> split(const std::string& s, char delim) {
        std::vector<std::string> result;
        std::istringstream iss(s);
        std::string item;
        while (std::getline(iss, item, delim)) result.push_back(item);
        return result;
    }

    tcp::acceptor acceptor_;
    std::shared_ptr<TokenGenerator> token_gen_;
    std::unordered_map<std::string, std::string> sessions_;
    std::unordered_map<std::string, std::shared_ptr<ChatRoom>> rooms_;
};

int main() {
    boost::asio::io_context ctx;
    ChatServer server(ctx, 8080);
    boost::asio::co_spawn(ctx, server.run(), boost::asio::detached);
    ctx.run();
    return 0;
}
